@Service
public class BillingService {

    @Autowired
    private AuditLogService auditLogService;

    @Autowired
    private InvoiceRepository invoiceRepository;

    @Transactional(propagation = Propagation.REQUIRED)
    public void processInvoice(Invoice invoice) {
        invoiceRepository.save(invoice);
        try {
            // REQUIRES_NEW ensures audit log is written even if billing fails later
            auditLogService.recordAuditTrail("INVOICE_PROCESSED", invoice.getId());
        } catch (Exception e) {
            // Handle audit failure separately
        }
        if (invoice.getAmount().compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("Invalid amount");
        }
    }
}

@Service
public class AuditLogService {

    @Autowired
    private AuditRepository auditRepository;

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void recordAuditTrail(String action, Long entityId) {
        auditRepository.save(new AuditLog(action, entityId));
    }
}
